import{_ as t,o as i,c as o,a5 as c}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-2-assign-task-to-creator/report3_spec.md","filePath":"feature/content-task-workflow/3-6-2-assign-task-to-creator/report3_spec.md"}'),e={name:"feature/content-task-workflow/3-6-2-assign-task-to-creator/report3_spec.md"};function r(l,n,s,h,a,g){return i(),o("div",null,[...n[0]||(n[0]=[c("<p><strong>3.6.2 Assign Task To Creator</strong></p><p><strong>Function Trigger</strong></p><p>Begins when Manager thực hiện thao tác trên giao diện <code>TaskDetailUI</code> liên quan đến tính năng <code>Assign Task To Creator</code>.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Manager.</li><li><strong>Purpose</strong>: Gắn công việc cho người làm và người chịu trách nhiệm check lại công việc đó.</li><li><strong>Interface</strong>: Giao diện <code>TaskDetailUI</code> hiển thị trực quan các thành phần thao tác, dữ liệu và phản hồi trạng thái.</li><li><strong>Data Processing</strong>: Tiếp nhận yêu cầu tại <code>TaskController</code>, xác thực quyền của caller, thực thi kiểm tra và xử lý nghiệp vụ thông qua <code>TaskService</code>, truy xuất và cập nhật cơ sở dữ liệu thông qua Repository tương ứng.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Screen Layout (<code>TaskDetailUI</code>):</p><ul><li>Header: Tiêu đề trang, breadcrumb điều hướng và thông tin định danh ngữ cảnh làm việc.</li><li>Main Workspace: Khu vực hiển thị bảng dữ liệu, biểu mẫu nhập liệu hoặc danh sách đối tượng nghiệp vụ.</li><li>Action Panel: Các nút điều khiển thực hiện hành động chính, nút hủy và các bộ lọc tìm kiếm.</li><li>Feedback Area: Khu vực hiển thị trạng thái xử lý (loading spinner, modal xác nhận, toast thông báo kết quả).</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: Các trường bắt buộc theo đặc tả của <code>POST /api/v1/workspaces/{workspaceId}/tasks/{taskId}/assign</code>.</li><li><strong>Input optional</strong>: Các tham số lọc, phân trang hoặc ghi chú bổ sung.</li><li><strong>System data</strong>: Bản ghi dữ liệu liên quan tại các bảng cơ sở dữ liệu (<code>TaskRepository, WorkspaceMemberRepository</code>).</li><li><strong>Output</strong>: <code>TaskResponse</code> kèm mã trạng thái HTTP tiêu chuẩn.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-362</strong>: Chỉ các Actor có thẩm quyền hợp lệ (<code>Manager</code>) mới được phép kích hoạt tính năng.</li><li>Đảm bảo tính toàn vẹn dữ liệu và kiểm tra xung đột trạng thái trước khi thực hiện thay đổi dữ liệu.</li><li>Mọi thao tác đều được ghi nhận nhật ký hệ thống phục vụ công tác kiểm toán và giám sát.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Thiếu hoặc sai định dạng tham số bắt buộc → Trả về HTTP 400 <code>BAD_REQUEST</code>.</li><li>Token không hợp lệ hoặc hết hạn → Trả về HTTP 401 <code>UNAUTHORIZED</code>.</li><li>Không đủ thẩm quyền vai trò → Trả về HTTP 403 <code>FORBIDDEN</code>.</li><li>Bản ghi đối tượng không tồn tại → Trả về HTTP 404 <code>NOT_FOUND</code>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Người dùng mở giao diện <code>TaskDetailUI</code>.</li><li>Giao diện gửi yêu cầu <code>POST /api/v1/workspaces/{workspaceId}/tasks/{taskId}/assign</code> tới <code>TaskController</code>.</li><li><code>TaskController</code> điều phối xử lý sang <code>TaskService.processRequest()</code>.</li><li>Hệ thống thực hiện kiểm tra và xử lý dữ liệu nghiệp vụ.</li><li>Hệ thống trả dữ liệu <code>TaskResponse</code> về giao diện hiển thị cho người dùng.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Token xác thực không hợp lệ hoặc hết hạn → Hệ thống hiển thị thông báo lỗi và yêu cầu đăng nhập lại.</li><li>3.a1: Dữ liệu đầu vào không thỏa mãn ràng buộc nghiệp vụ → Hệ thống báo lỗi chi tiết tại từng trường nhập liệu.</li><li>4.a1: Đối tượng yêu cầu không tồn tại trong hệ thống → Hiển thị thông báo không tìm thấy bản ghi tương ứng.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Trạng thái hệ thống được cập nhật chính xác theo kết quả xử lý của tính năng <code>Assign Task To Creator</code>.</li><li>Người dùng nhận được phản hồi trực quan trên giao diện và luồng nghiệp vụ được tiếp diễn theo kế hoạch.</li></ul>",14)])])}const d=t(e,[["render",r]]);export{p as __pageData,d as default};
